      '.dra-dialog{background:var(--dra-sheen),var(--dra-glass-strong);backdrop-filter:blur(28px) saturate(1.6);-webkit-backdrop-filter:blur(28px) saturate(1.6);border:1px solid var(--dra-border);border-radius:var(--dra-r-xl);box-shadow:var(--dra-hl),var(--dra-elev-3);padding:22px 26px;max-width:460px;width:90vw;animation:dra-pop .4s var(--dra-spring) both}',
