      '@media (forced-colors:active){.dra-tab[aria-selected="true"]{border:2px solid Highlight}.dra-btn,.dra-card,.dra-fold,.dra-banner,.dra-stat{border:1px solid CanvasText}.dra-aurora{display:none}}',
      /* 不支持毛玻璃或用户要求减少透明度：换成实色面，层次靠阴影与边框保留。 */
      '@supports not (backdrop-filter:blur(1px)){.dra-card,.dra-fold,.dra-stat,.dra-tabs,.dra-banner{background:var(--dra-surface-1)}.dra-drawer,.dra-dialog{background:var(--dra-surface-1)}}',
      '@media (prefers-reduced-transparency:reduce){.dra-card,.dra-fold,.dra-stat,.dra-tabs,.dra-banner{background:var(--dra-surface-1);backdrop-filter:none;-webkit-backdrop-filter:none}.dra-drawer,.dra-dialog{background:var(--dra-surface-1);backdrop-filter:none;-webkit-backdrop-filter:none}.dra-drawer-wrap,.dra-dialog-overlay{backdrop-filter:none;-webkit-backdrop-filter:none}}',
